// Add "Confirm Received" button in My Account > Orders
function add_confirm_received_button($actions, $order) {
    // Ensure the button only appears for orders that are not yet completed
    if ($order->has_status('shipped')) {
        $actions['confirm_received'] = array(
            'url'  => wp_nonce_url(
                add_query_arg('confirm_received', $order->get_id()),
                'woocommerce-confirm-received'
            ),
            'name' => __('Konfirmasi Diterima', 'woocommerce'),
            'class' => 'button confirm-received',
        );
    }
    return $actions;
}
add_filter('woocommerce_my_account_my_orders_actions', 'add_confirm_received_button', 10, 2);

// Handle the confirmation action
function handle_confirm_received() {
    if (isset($_GET['confirm_received']) && isset($_GET['_wpnonce']) && wp_verify_nonce($_GET['_wpnonce'], 'woocommerce-confirm-received')) {
        $order_id = intval($_GET['confirm_received']);
        $order = wc_get_order($order_id);
        if ($order && $order->get_status() !== 'completed') { // Ensure order is not already completed
            $order->update_status('completed'); // Change status to completed
            wc_add_notice(__('Thank you for confirming that you have received your order.', 'woocommerce'), 'success');
            wp_redirect(wc_get_account_endpoint_url('orders'));
            exit;
        }
    }
}
add_action('template_redirect', 'handle_confirm_received');

