add_action( 'woocommerce_thankyou', 'webappick_override_order_status_to_pending', 999, 1 );

function webappick_override_order_status_to_pending( $order_id ) {
    if ( ! $order_id ) return;

    $order = wc_get_order( $order_id );

    // Check if the initial status change has already been performed
    if ( ! $order->get_meta( '_initial_status_set' ) ) {
        // Update the order status to 'pending' and add a note
        if($order->get_payment_method() === 'cod'){
            $order->update_status( 'waiting-conf', 'Order status set to waiting confirmation to shipping' );
        }

        // Set a meta key to prevent this from running again
        $order->update_meta_data( '_initial_status_set', true );
        $order->save();
    }
}


