add_action( 'dokan_new_product_form', 'add_dokan_custom_profit_share_field' );
// Save custom "Profit Share" field data
function save_dokan_custom_profit_share_field( $post_id ) {
  if (!isset($_POST['shopbiz_product_meta_box_nonce'])) { 
    return;
  }

  // Verify nonce
  if (!wp_verify_nonce($_POST['shopbiz_product_meta_box_nonce'], 'shopbiz_save_product_meta_box')) {
    return;
  }

  // Check if autosave
  if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
    return;
  }



  // Save meta box data
  if (isset($_POST['PS'])) {
    update_post_meta($post_id, 'PS', sanitize_text_field($_POST['PS']));
  }
}
