// Filter order by status
function custom_order_status_filter() {
    if (is_account_page() && is_wc_endpoint_url('orders')) {
        $statuses = wc_get_order_statuses();
        $current_status = isset($_GET['order_status']) ? wc_clean($_GET['order_status']) : '';

        echo '<form method="GET" action="' . esc_url(wc_get_account_endpoint_url('orders')) . '">';
        echo '<select name="order_status" onchange="this.form.submit()" class="selection">';
        echo '<option value="">' . esc_html__('All Orders', 'woocommerce') . '</option>';

        foreach ($statuses as $status_slug => $status_name) {
            echo '<option value="' . esc_attr($status_slug) . '" ' . selected($current_status, $status_slug, false) . '>' . esc_html($status_name) . '</option>';
        }

        echo '</select>';
        echo '</form>';
    }
}


add_action('woocommerce_before_account_orders', 'custom_order_status_filter');

function filter_woocommerce_my_account_orders_query($args) {
    if (is_account_page() && is_wc_endpoint_url('orders') && isset($_GET['order_status']) && $_GET['order_status'] != '') {
        $args['status'] = wc_clean($_GET['order_status']);
    }
    return $args;
}
add_filter('woocommerce_my_account_my_orders_query', 'filter_woocommerce_my_account_orders_query');

