function display_total_cart_points_shortcode($atts) {
    // Set default attributes and merge with passed attributes
    $atts = shortcode_atts(
        array(
            'user_id' => get_current_user_id(),  // Default to the current user's ID
            'enable_refresh' => 'no',           // Default to 'no' to hide the refresh button
        ),
        $atts,
        'total_cart_points'
    );

    // Extract the attributes
    $user_id = $atts['user_id'];
    $enable_refresh = $atts['enable_refresh'];

    // Ensure WooCommerce is active and cart is available
    if ( ! class_exists( 'WooCommerce' ) || ! WC()->cart ) {
        return 'WooCommerce is not active or cart is not available.';
    }

    // Initial points calculation
    $total_points = calculate_total_cart_points($user_id);

    // Start building the output HTML
    $output = '<div id="yith-par-message-cart" class="woocommerce-cart-notice woocommerce-cart-notice-minimum-amount woocommerce-info" style="display: flex; justify-content: space-between; align-items: center;">';
    
    // Add image and message
    $output .= '<div><img decoding="async" style="max-width: 35px; margin-right: 5px;" src="https://shopbiz.id/wp-content/plugins/yith-woocommerce-points-and-rewards-premium/assets/images/prize.svg">';
    $output .= 'Setelah pesanan selesai, kamu akan mendapatkan&nbsp;<strong>' . $total_points . '</strong> Point Level!</div>';
    
    // Conditionally add the refresh button based on the enable_refresh attribute
    if ( strtolower($enable_refresh) === 'yes' ) {
        $output .= '<a href="#" id="refresh-points" class="button" style="margin-left: auto;">Perbarui</a>';

        // Add inline JavaScript to handle AJAX request
        $output .= '<script type="text/javascript">
            jQuery(document).ready(function($) {
                $("#refresh-points").on("click", function() {
                    $.ajax({
                        url: "' . admin_url('admin-ajax.php') . '",
                        type: "POST",
                        data: {
                            action: "refresh_total_cart_points",
                            user_id: ' . esc_js($user_id) . '
                        },
                        success: function(response) {
                            $("#total-points").html(response);
                        }
                    });
                });
            });
        </script>';
    }

    $output .= '</div>';

    return $output;
}



function calculate_total_cart_points() {
    $cart = WC()->cart;

    // Check if the cart is empty
    if ( $cart->is_empty() ) {
        return 0;
    }

    $total_points = 0;

    // Calculate points for single products
    $total_points += calculate_single_product_points($cart);

    // Calculate points for variable products
    $total_points += calculate_variable_product_points($cart);

    return $total_points;
}


function calculate_single_product_points($cart) {
    $points = 0;

    foreach ( $cart->get_cart() as $cart_item_key => $cart_item ) {
        // Only consider single products (not variations)
        if ( ! isset( $cart_item['variation_id'] ) || $cart_item['variation_id'] == 0 ) {
            $product_id = $cart_item['product_id'];
            $quantity = $cart_item['quantity']; // Get the quantity of the product in the cart

            // Retrieve and handle the MyCred reward meta data
            $meta_data = get_post_meta( $product_id, 'mycred_reward', true );
            $mycred_reward = maybe_unserialize( $meta_data );

            if ( is_array( $mycred_reward ) && isset( $mycred_reward['point_level'] ) ) {
                $point_level = intval( $mycred_reward['point_level'] ); // Ensure it's an integer
                $points += $point_level * $quantity; // Add to total points
            }
        }
    }

    return $points;
}

function calculate_variable_product_points($cart) {
    $points = 0;

    foreach ( $cart->get_cart() as $cart_item_key => $cart_item ) {
        // Only consider variations
        if ( isset( $cart_item['variation_id'] ) && $cart_item['variation_id'] > 0 ) {
            $variation_id = $cart_item['variation_id'];
            $quantity = $cart_item['quantity']; // Get the quantity of the variation in the cart

            // Retrieve and handle the MyCred reward meta data
            $serialized_reward = get_post_meta( $variation_id, '_mycred_reward', true );
            $mycred_reward = maybe_unserialize( $serialized_reward );

            if ( is_array( $mycred_reward ) && isset( $mycred_reward['point_level'] ) ) {
                $point_level = intval( $mycred_reward['point_level'] ); // Ensure it's an integer
                $points += $point_level * $quantity; // Add to total points
            }
        }
    }

    return $points;
}

add_shortcode( 'total_cart_points', 'display_total_cart_points_shortcode' );
function refresh_total_cart_points() {
    // Calculate total points
    $total_points = calculate_total_cart_points();

    // Return the updated points
    echo $total_points;

    // Stop further processing
    wp_die();
}
add_action( 'wp_ajax_refresh_total_cart_points', 'refresh_total_cart_points' );
add_action( 'wp_ajax_nopriv_refresh_total_cart_points', 'refresh_total_cart_points' );


