            document.getElementById('foto_ktp').value = result.foto_ktp;
            document.getElementById('nama_bank').value = result.bank;
            document.getElementById('owner_name').value =result.nama;
            document.getElementById('no_rek').value = result.rekening;
            document.getElementById('password_transaksi').value = userData.passwordTransaksi;

