                    imgElement.style.display = 'block';
                }
                $('#upgradeModal').fadeIn();
            }
          
        });

        // Close modal when clicking on the close button
        $('.close').on('click', function() {
            $('#upgradeModal').fadeOut();
        });

        // Handle form submission
        $('#upgradeForm').on('submit', function(e) {
            e.preventDefault();
            $('#submit-upgrade').attr('disabled', 'disabled').text('Mengirim...');
			let localTime = new Date().toISOString();  // ISO format

			// Store the local time in a hidden input or session
			document.getElementById('local_time_input').value = localTime;
            var formData = new FormData(this);
            formData.append('action', 'shopbiz_upgrade');
            formData.append('nonce', '<?php echo wp_create_nonce('shopbiz-upgrade-nonce'); ?>');
			// Capture the user's local time
			
            $.ajax({
                url: '<?php echo admin_url('admin-ajax.php'); ?>',
                type: 'POST',
                data: formData,
                processData: false,
                contentType: false,
                success: function(response) {
                    if (response.success) {
						$('#upgradeModal .modal-content').html('<h2>Berhasil!</h2><p>' + response.message + '</p>');
						$('#upgradeModal').fadeIn();

						setTimeout(function() {
							location.reload(); 
						}, 2000); 
                    } else {
						$('#upgradeModal').fadeOut();
                        $('.woocommerce-message').addClass('woocommerce-error').html(response.message).show();
                    }
                    $('#submit-upgrade').removeAttr('disabled').text('Submit');
                }
            });
        });
		
    });
		
	const loginButton = document.getElementById('login-mlm');
		
	if(loginButton){
		document.getElementById('login-mlm').addEventListener('click', function(event) {
