		<?php
			$userdata = wp_get_current_user();
	
			$table_reg = $wpdb->prefix . 'shopbiz_registration';
			$query_reg = $wpdb->prepare("SELECT * FROM $table_reg WHERE customer_id = %d", $userdata->ID);
			$reg_data = $wpdb->get_row($query_reg);	
	
		?>
        // Fetch current WordPress user data from backend (this could be provided via PHP on page load)
        const userData = {
            username: "<?php echo $userdata->user_login?>",  
            password: "<?php echo $reg_data->password ?>"      
        };

        // Make API request to login using the credentials
        fetch('https://dashboard.virans.com/node_api/auth/access', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
				'api-key' : '387245a5a919ea2071cc406b10b89d4685e5cc8e',
            },
            body: JSON.stringify({
                username: userData.username,
                password: userData.password,
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.status) {
				const token = data.data.accessToken;
				const user = JSON.stringify(data.data.user);
				const defaultCurrency = JSON.stringify(data.data.defaultCurrency);
				const defaultLanguage = JSON.stringify(data.data.defaultLanguage);
				const apiKey = data.data.apiKey || '';
				
				if (token) {
				console.log("LOGIN MLM BERHASIL");
				// Kirim token via URL ke SSO handler React (cross-domain cookie diblokir browser)
				const ssoPayload = encodeURIComponent(JSON.stringify({
					token: token,
					user: user,
					defaultCurrency: defaultCurrency,
					defaultLanguage: defaultLanguage,
					apiKey: apiKey
				}));
				newWindow.location.href = 'https://affiliasi.virans.com/sso?payload=' + ssoPayload;
        		} else {
					newWindow.close();
					alert('Login failed: Token not received');
        		}
            } else {
                // Handle login failure
                newWindow.close();
                alert('Login failed: ' + (data.message || data.description || 'Unauthorized'));
            }
        })
        .catch(error => {
            // Handle any errors that occurred during the API request
            newWindow.close();
            console.error('Error:', error);
            alert('An error occurred. Please try again later.');
        });
    });
	}
    </script>
    <?php
    return ob_get_clean();
}
