function get_cart_items_by_type() {
    $affiliate_products = [];
    $non_affiliate_products = [];
    $affiliate_products_key = [];
    $non_affiliate_products_key = [];

    foreach ( WC()->cart->get_cart() as $cart_item_key => $cart_item ) {
        $product_id = $cart_item['product_id'];
        $is_affiliate = get_post_meta( $product_id, '_is_affiliate_product', true );
        $cart = ['product_id' => $cart_item['product_id'],'quantity' => $cart_item['quantity']] ;
        if ( $is_affiliate  == 'yes') {
            $affiliate_products[] = $cart;
            $affiliate_products_key[] = $cart_item_key;
        }else{
            $non_affiliate_products[] = $cart;
            $non_affiliate_products_key[] = $cart_item_key;
        }
    }
    return [
        'affiliate_key' => $affiliate_products_key,
        'non_affiliate_key' => $non_affiliate_products_key,
        'affiliate' => $affiliate_products,
        'non_affiliate' => $non_affiliate_products
    ];
}

function disable_payment_for_affiliate_checkout( $available_gateways ) {
    if ( is_page( 'checkout-affiliate' ) ) {
        // Misalnya kita hanya ingin metode pembayaran bernama 'marketplace_payment' yang tersedia
        $allowed_gateways = array( 'cod' ); // ID gateway yang diizinkan
        foreach ( $available_gateways as $gateway_id => $gateway ) {
            if ( ! in_array( $gateway_id, $allowed_gateways ) ) {
                unset( $available_gateways[$gateway_id] ); // Hapus gateway lain yang bukan marketplace
            }
        }
    }
    return $available_gateways;
}
add_filter( 'woocommerce_available_payment_gateways', 'disable_payment_for_affiliate_checkout' );

