// Proses data konfirmasi pembayaran
function affiliate_process_payment_confirmation( $order_id ) {
    if ( isset( $_POST['submit_affiliate_payment'] ) ) {
        // Ambil data dari form
        $product_ids      = isset( $_POST['product_ids'] ) ? $_POST['product_ids'] : array();
        $item_ids         = isset( $_POST['item_ids'] ) ? $_POST['item_ids'] : array();
        $marketplace_names = isset( $_POST['marketplace_names'] ) ? $_POST['marketplace_names'] : array();
        $transaction_ids  = isset( $_POST['transaction_ids'] ) ? $_POST['transaction_ids'] : array();
        $other_marketplaces = isset( $_POST['other_marketplaces'] ) ? $_POST['other_marketplaces'] : array();

        if ( count( $product_ids ) === count( $marketplace_names ) ) {
            $payment_confirmations = array();

            foreach ( $product_ids as $index => $product_id ) {
                $item_id         = $item_ids[$index];
                $marketplace_name = sanitize_text_field( $marketplace_names[$index] );
                $transaction_id  = sanitize_text_field( $transaction_ids[$index] );

                // Jika pengguna memilih "Lainnya", gunakan input dari other_marketplaces[]
                if ( $marketplace_name === "lainnya" && isset( $other_marketplaces[$index] ) ) {
                    $marketplace_name = sanitize_text_field( $other_marketplaces[$index] );
                }

                $confirmation_data = array(
                    'product_id'       => $product_id,
                    'item_id'          => $item_id,
                    'marketplace_name' => $marketplace_name,
                    'transaction_id'   => $transaction_id,
                );

                $payment_confirmations[] = $confirmation_data;

                // Simpan ke order meta
                update_post_meta( $order_id, '_affiliate_payment_confirmation', $payment_confirmations );
                
				$order = wc_get_order( $order_id );
                $order->update_status( 'wc-waiting-conf', 'Pembayaran dikonfirmasi, menunggu konfirmasi manual.' );
            }

            // Redirect setelah sukses
            wp_redirect( wc_get_account_endpoint_url( 'orders' ) );
            exit;
        } else {
            echo '<p class="woocommerce-error">Terjadi kesalahan pada pengisian form. Silakan coba lagi.</p>';
        }
    }
}
