function save_affiliate_poin_data( $order_id ) {
    $order = wc_get_order( $order_id );

    // Sekarang gunakan dua tipe poin
    $point_types = ['point_level', 'point_upgrade'];
    $internal_point_type = 'point_seller_internal'; // untuk vendor/sales

    $total_payout = 0;
    $buyer_id = $order->get_user_id();

    // Cek apakah data poin dikirim dari AJAX
    $poin_level_affiliate = get_post_meta( $order_id, 'poin_level_affiliate', true );
    error_log('POINT LEVEL AFFILIATE: ' . print_r($poin_level_affiliate, true));

    if ( empty( $poin_level_affiliate ) ) {
        return;
    }

    // Hitung total payout
    $i = 0;
    foreach ( $order->get_items() as $item ) {
        $quantity = $item->get_quantity();
        $poin_per_item = intval( sanitize_text_field( $poin_level_affiliate[$i] ?? 0 ) );
        $total_payout += $poin_per_item * $quantity;
        $i++;
    }

    error_log("Total poin yang akan ditambahkan: " . $total_payout);
    error_log("ID Pembeli: " . $buyer_id);

    if ( $total_payout == 0 ) {
        return;
    }

    // Simpan meta poin order
    update_post_meta( $order_id, 'poin_level_affiliate', $poin_level_affiliate );

    // Catat di order note
    $i = 0;
    foreach ( $order->get_items() as $item ) {
        $product_id = $item->get_product_id();
        $product_point = intval( sanitize_text_field( $poin_level_affiliate[$i] ?? 0 ) );
        $quantity = $item->get_quantity();

        $order->add_order_note( 
            sprintf(
                'Admin menambahkan poin afiliasi sebesar %d untuk produk ID %d (Kuantitas: %d)',
                $product_point,
                $product_id,
                $quantity
            ),
            false
        );
        $i++;
    }

    // 🔹 Loop setiap tipe poin dan tambahkan ke pembeli
    foreach ( $point_types as $point_type ) {
        $mycred = mycred( $point_type );

        if ( ! $mycred ) {
            error_log("MYCRED point type $point_type tidak ditemukan.");
            continue;
        }

        $reference = apply_filters( 'mycred_woo_reward_reference', 'reward', $order_id, $point_type );
        $log       = apply_filters( 'mycred_woo_reward_log', '%plural% reward for store purchase Affiliate Product', $order_id, $point_type );

        $mycred->add_creds(
            $reference,
            $buyer_id,
            $total_payout,
            $log,
            $order_id,
            array( 'ref_type' => 'post' ),
            $point_type
        );

        error_log("MYCRED ($point_type): +$total_payout poin ke user $buyer_id");
    }

    // 🔹 Kurangi poin vendor internal
    $i = 0;
    foreach ( $order->get_items() as $item ) {
        $product_id = $item->get_product_id();
        $vendor_id  = get_post_field( 'post_author', $product_id );
        $poin_per_item = intval( sanitize_text_field( $poin_level_affiliate[$i] ?? 0 ) );
        $deduction_points = $poin_per_item;

        if ( $vendor_id ) {
            $internal_log = apply_filters( 'mycred_woo_deduct_log', '%plural% deduction for customer reward points', $order_id, $internal_point_type );
            $mycred_internal = mycred( $internal_point_type );

            $mycred_internal->add_creds(
                'deduct',
                $vendor_id,
                -$deduction_points,
                $internal_log,
                $order_id,
                array( 'ref_type' => 'post' ),
                $internal_point_type
            );

            error_log("MYCRED ($internal_point_type): -$deduction_points poin dari vendor $vendor_id");
        }

        $i++;
    }
}



