function custom_cart_with_affiliate_data() { 
    if ( WC()->cart == null ) {
        ob_start();
        wc_get_template( 'cart/cart-empty.php' );
        return ob_get_clean();
    } else {
        return wc_get_template( 'cart/cart.php' );
    }
}
