function custom_handle_affiliate_checkout() {
    // Periksa nonce untuk keamanan
    if ( ! isset( $_POST['nonce'] ) || ! wp_verify_nonce( $_POST['nonce'], 'wc_cart_nonce' ) ) {
        wp_send_json_error( 'Nonce verification failed.' );
    }

    // Pastikan pengguna login
    if ( ! is_user_logged_in() ) {
        wp_send_json_error( 'Harus Login untuk melakukan pemesanan' );
    }

    // Buat pesanan secara manual
    try {
        $order = wc_create_order();

        // Tambahkan semua item dari keranjang ke pesanan
        foreach ( WC()->cart->get_cart() as $cart_item_key => $cart_item ) {
            $product_id   = $cart_item['product_id'];
            $variation_id = $cart_item['variation_id'];
            $quantity     = $cart_item['quantity'];
            $product      = wc_get_product( $variation_id ? $variation_id : $product_id );

            // Tambahkan produk atau variasi produk ke pesanan
            if ( $product ) {
                $order->add_product( $product, $quantity );
            }
        }

        // Set detail pelanggan (ambil dari sesi WooCommerce)
        $user_id = get_current_user_id();
        $order->set_customer_id( $user_id );
        $order->set_address( WC()->customer->get_billing(), 'billing' );
        $order->set_address( WC()->customer->get_shipping(), 'shipping' );

        $order->calculate_totals();
        $order_total = $order->get_total();
        $order->update_status( 'pending' );

		// Get seller ID associated with the order (this line is added)
    	$seller_id = dokan_get_seller_id_by_order_id($order->get_id());

   		// Update the order meta data for vendor ID
    	$order->update_meta_data('_dokan_vendor_id', $seller_id);
		$order->save();
		dokan_sync_insert_order( $order->get_id() );
        // Kosongkan keranjang setelah pesanan dibuat
        WC()->cart->empty_cart();

        // Redirect ke halaman "Thank You"
        $redirect_url = $order->get_checkout_order_received_url();
		
        wp_send_json_success( [ 'redirect_url' => $redirect_url ] );
    } catch ( Exception $e ) {
        wp_send_json_error( 'Error creating order: ' . $e->getMessage() );
    }
}

