add_action('woocommerce_save_account_details', 'hit_api_on_account_update', 10, 1);

function hit_api_on_account_update($user_id) {
    // Retrieve the new password from POST
    $new_password = !empty($_POST['password_1']) ? sanitize_text_field($_POST['password_1']) : '';

    // If no new password was set, exit early
    if (empty($new_password)) {
        return;
    }

    // Check if the user has a corresponding shopbiz_user_id meta
    $userId = get_user_meta($user_id, 'shopbiz_user_id', true);
    if ($userId) {
        // Prepare the API URL and data
        $api_url = 'https://dashboard.virans.com/node_api/update-password-wp'; // Replace with your API URL
        $api_data = array(
            'user_id'      => $userId,
            'new_password' => $new_password
        );

        // Send POST request to the API
        $response = wp_remote_post($api_url, array(
            'method'    => 'POST',
            'body'      => json_encode($api_data),
            'headers'   => array(
                'Content-Type' => 'application/json',
                'api-key'      => get_option('shopbiz_api_mlm_api_key')
            ),
            'sslverify' => false
        ));

        // Log errors if any
        if (is_wp_error($response)) {
            error_log('CHANGE PASSWORD ERROR: ' . $response->get_error_message());
        } else {
            error_log('Password updated via API for user ID: ' . $user_id);
        }

        // Update password in the shopbiz_registration table
        global $wpdb;
        $table_reg = $wpdb->prefix . 'shopbiz_registration';
        $wpdb->update(
            $table_reg,
            array(
                'password' => $new_password // Make sure to hash the password before saving it
            ),
            array('customer_id' => $user_id),
            array('%s'),
            array('%d')
        );
    }
}

