// Group orders by date in the My Account orders page
add_action('woocommerce_account_orders_endpoint', 'group_orders_by_date');
function group_orders_by_date() {
    // Get customer orders based on selected status
    $status = isset($_GET['order_status']) ? wc_clean($_GET['order_status']) : '';
    $args = array(
        'customer' => get_current_user_id(),
        'status' => $status ? $status : 'any',
        'orderby' => 'date',
        'order' => 'DESC',
    );
    $customer_orders = wc_get_orders($args);

    if (!empty($customer_orders)) {
        $orders_by_date = [];

        // Group orders by date
        foreach ($customer_orders as $order) {
            // Check if the order is a main order (has sub-orders)
            if ($order->get_meta('has_sub_order') == '1') {
                continue; // Skip main orders
            }
            $date = $order->get_date_created()->date('Y-m-d');
            $orders_by_date[$date][] = $order;
        }

        // Display grouped orders
        foreach ($orders_by_date as $date => $orders) {
            echo '<h2>' . date_i18n('F j, Y', strtotime($date)) . '</h2>'; // Date header

            echo '<table class="woocommerce-orders-table woocommerce-MyAccount-orders shop_table shop_table_responsive my_account_orders account-orders-table custom-orders-table">';
            echo '<thead><tr>';
            echo '<th class="woocommerce-orders-table__header woocommerce-orders-table__header-order-number"><span>' . __('Order', 'woocommerce') . '</span></th>';
            echo '<th class="woocommerce-orders-table__header woocommerce-orders-table__header-vendor-name"><span>' . __('Vendor', 'woocommerce') . '</span></th>'; // New Vendor column
            echo '<th class="woocommerce-orders-table__header woocommerce-orders-table__header-order-status"><span>' . __('Status', 'woocommerce') . '</span></th>';
            echo '<th class="woocommerce-orders-table__header woocommerce-orders-table__header-order-total"><span>' . __('Total', 'woocommerce') . '</span></th>';
            echo '<th class="woocommerce-orders-table__header woocommerce-orders-table__header-order-actions"><span class="nobr">' . __('Actions', 'woocommerce') . '</span></th>';
            echo '</tr></thead>';
            echo '<tbody>';

            // Loop through orders in this date group
            $vendor_names = []; 
            foreach ($orders as $order) {
                $order_id = $order->get_id();
                echo '<tr class="woocommerce-orders-table__row woocommerce-orders-table__row--status-' . esc_attr($order->get_status()) . ' order">';
                echo '<td class="woocommerce-orders-table__cell woocommerce-orders-table__cell-order-number"><a href="' . esc_url($order->get_view_order_url()) . '">' . $order->get_order_number() . '</a></td>';
                // Vendor Name Column
                echo '<td class="woocommerce-orders-table__cell woocommerce-orders-table__cell-vendor-name">';
                $vendor_names = []; // To store unique vendor names for the order
                foreach ($order->get_items() as $item_id => $item) {
                    $product_id = $item->get_product_id();
                    $vendor_id = get_post_field('post_author', $product_id); // Get the vendor ID (product's author ID)
                     // Check if the vendor has a store name set (for Dokan)
                    $vendor_store_name = get_user_meta($vendor_id, 'dokan_store_name', true); // Dokan store name field
                    
                    // If store name is not set, fall back to the display name
                    if (!$vendor_store_name) {
                        $vendor_store_name = get_the_author_meta('display_name', $vendor_id);
                    }

                    if (!in_array($vendor_store_name, $vendor_names)) {
                        $vendor_names[] = $vendor_store_name; // Ensure no duplicate vendor names
                    }
                }
                echo implode(', ', $vendor_names); // Display vendor names
                echo '</td>';
                // echo '<td class="woocommerce-orders-table__cell woocommerce-orders-table__cell-order-date">' . wc_format_datetime($order->get_date_created()) . '</td>';
                echo '<td class="woocommerce-orders-table__cell woocommerce-orders-table__cell-order-status" style="text-align:left; white-space:nowrap;">' . wc_get_order_status_name($order->get_status()) . '</td>';
                echo '<td class="woocommerce-orders-table__cell woocommerce-orders-table__cell-order-total">' . $order->get_formatted_order_total() . '</td>';
                echo '<td class="woocommerce-orders-table__cell woocommerce-orders-table__cell-order-actions">';

                // Retrieve and display custom order actions with modified "View" label
                $actions = wc_get_account_orders_actions($order);
                foreach ($actions as $key => $action) {
                    echo '<a href="' . esc_url($action['url']) . '" class="woocommerce-button button ' . sanitize_html_class($key) . '">' . esc_html($action['name']) . '</a>';
                }

                echo '</td>';
                echo '</tr>';
            }

            echo '</tbody>';
            echo '</table>';
        }
    } else {
        echo '<p>' . __('No orders found.', 'woocommerce') . '</p>';
    }
}

