// Create a custom shortcode for the cart button with icon, quantity, and inline CSS
function custom_cart_button_shortcode() {
    // Get the cart contents count
    $cart_count = WC()->cart->get_cart_contents_count();

    // Output the cart button HTML with icon and quantity
    $button_html = '
        <a href="#" id="custom-cart-button" class="custom-cart-button">
            <span class="cart-icon" aria-hidden="true">
                <i class="fa-solid fa-shopping-cart"></i> <!-- FontAwesome shopping cart icon -->
                <span class="cart-quantity">' . esc_html($cart_count) . '</span>
            </span>
        </a>
    ';

    // Inline CSS for styling
    $inline_css = '
        <style>
            #custom-cart-button {
                display: inline-flex; /* Use flexbox for alignment */
                align-items: center; /* Center the items vertically */
                padding: 0; /* Button padding */
                color: black; /* Button text color */
                text-decoration: none; /* Remove underline */
                border-radius: 5px; /* Rounded corners */
                position: relative; /* Enable positioning for the quantity badge */
            }

            .cart-icon {
                position: relative; /* Position the icon relative to the button */
                margin-right: 5px; /* Space between icon and quantity */
            }

            .cart-quantity {
                position: absolute; /* Position the quantity badge absolutely */
                top: -5px; /* Adjust this value to position it correctly */
                right: -10px; /* Adjust this value to position it correctly */
                color: #ffffff; /* Text color for quantity */
                padding: 5px; /* Padding for quantity */
                border-radius: 50%; /* Make it circular */
                font-size: 12px; /* Font size */
                background-color: darkorange; /* Background color for quantity */
                border: 2px solid #ffffff; /* Optional: border for better visibility */
                text-align: center; /* Center text in the badge */
                min-width: 20px; /* Minimum width to ensure it is a circle */
                height: 20px; /* Fixed height for the circle */
                line-height: 8px; /* Center text vertically */
				font-weight: bold;
            }

            /* Hover effect */
            #custom-cart-button:hover {
                color: grey; /* Darker background on hover */
            }
        </style>
    ';

    // Enqueue FontAwesome for cart icon
    wp_enqueue_style('font-awesome', 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css');

    // Return the button HTML and inline CSS
    return $button_html . $inline_css;
}
add_shortcode('custom_cart_button', 'custom_cart_button_shortcode');

