// Get min and max prices for WooCommerce products
function get_woocommerce_price_range() {
    global $wpdb;

    // Query to get minimum and maximum price from all published products, including variations
    $min_price = $wpdb->get_var("
        SELECT MIN(CAST(meta_value AS UNSIGNED))
        FROM {$wpdb->postmeta} AS pm
        INNER JOIN {$wpdb->posts} AS p ON pm.post_id = p.ID
        WHERE pm.meta_key = '_price'
        AND p.post_status = 'publish'
        AND pm.meta_value REGEXP '^[0-9]+$'
    ");

    $max_price = $wpdb->get_var("
        SELECT MAX(CAST(meta_value AS UNSIGNED))
        FROM {$wpdb->postmeta} AS pm
        INNER JOIN {$wpdb->posts} AS p ON pm.post_id = p.ID
        WHERE pm.meta_key = '_price'
        AND p.post_status = 'publish'
        AND pm.meta_value REGEXP '^[0-9]+$'
    ");

    return [
        'min_price' => $min_price ?: 0,
        'max_price' => $max_price ?: 1000000, // Set a default if no products found
    ];
}

