        }
		
		#breadcrumbs {
			display: flex;
			align-items: center;
			padding: 10px; 
			background-color: 
		}
    </style>

<!--     <div class="filter-button-wrapper">
        <button class="filter-button">
            <i class="fas fa-filter"></i> Filter Produk
        </button>
    </div>

 -->
    <div class="filter-dialog">
        <!-- Price Range Slider -->
        <div class="filter-option">
            <label>Rentang Harga:</label>
            <div id="price-slider" class="price-slider"></div>
            <div class="price-range">
                <span>Rp</span><span id="price-min"><?php echo number_format($current_min_price, 0, ',', '.'); ?></span> - 
                <span>Rp</span><span id="price-max"><?php echo number_format($current_max_price, 0, ',', '.'); ?></span>
            </div>
        </div>

        <!-- Category Dropdown -->
        <div class="filter-option">
            <label for="category-filter">Category:</label>
            <select id="category-filter" name="category">
                <option value="">Pilih kategori</option>
                <?php
                // Recursive function to display categories with indentation
                function display_category_hierarchy($categories, $parent_id = 0, $level = 0, $current_category = '') {
                    foreach ($categories as $category) {
                        if ($category->parent == $parent_id) {
                            $indent = str_repeat('&nbsp;', $level * 4); // Indentation based on level
                            echo '<option value="' . esc_attr($category->slug) . '" ' . selected($current_category, $category->slug, false) . '>' . $indent . esc_html($category->name) . '</option>';
                            display_category_hierarchy($categories, $category->term_id, $level + 1, $current_category);
                        }
                    }
                }

                // Fetch all product categories with parent-child hierarchy
                $categories = get_terms(array(
                    'taxonomy' => 'product_cat',
                    'hide_empty' => true,
                ));
                display_category_hierarchy($categories, 0, 0, $current_category);
                ?>
            </select>
        </div>
		
        <button class="apply-filters">Terapkan Filter</button>
    </div>

    <script>
        jQuery(document).ready(function($) {
			$('#breadcrumbs').append('<button class="filter-button">' + '<i class="fas fa-filter"></i> Filter Produk</button>');

            // Show or hide the filter dialog
            $('.filter-button').on('click', function() {
                $('.filter-dialog').toggle();
            });
			
            // Initialize jQuery UI Range Slider with saved or default values
            $('#price-slider').slider({
                range: true,
                min: <?php echo $min_price; ?>,
                max: <?php echo $max_price; ?>,
                values: [<?php echo $current_min_price; ?>, <?php echo $current_max_price; ?>],
                slide: function(event, ui) {
                    $('#price-min').text(new Intl.NumberFormat('id-ID').format(ui.values[0]));
                    $('#price-max').text(new Intl.NumberFormat('id-ID').format(ui.values[1]));
                }
            });

            // Apply filters on button click
            $('.apply-filters').on('click', function() {
                const minPrice = $('#price-slider').slider('values', 0);
                const maxPrice = $('#price-slider').slider('values', 1);
                const category = $('#category-filter').val();

                // Create URL based on category slug
                let url = category ? `/product-category/${category}/` : '/shop/';
                url += `?min_price=${minPrice}&max_price=${maxPrice}`;

                // Redirect to the filtered URL
                window.location.href = url;
            });

            // Close dialog if clicking outside
            $(document).on('click', function(event) {
                if (!$('.filter-button').is(event.target) && !$('.filter-dialog').is(event.target) && $('.filter-dialog').has(event.target).length === 0) {
                    $('.filter-dialog').hide();
                }
            });
        });
    </script>
    <?php
}
