function custom_zip_code_search_script() {
    if (is_checkout() || dokan_is_seller_dashboard() || is_account_page()) {
        ?>
        <script type="text/javascript">
            jQuery(document).ready(function($) {
                // Debounce function to delay the AJAX call
                function debounce(func, wait) {
                    let timeout;
                    return function() {
                        const context = this;
                        const args = arguments;
                        clearTimeout(timeout);
                        timeout = setTimeout(function() {
                            func.apply(context, args);
                        }, wait);
                    };
                }

                function initializeZipCodeSelect(inputSelector) {
                    $(inputSelector).selectWoo({
                        minimumInputLength: 3, // Minimum characters to start search
                        ajax: {
                            url: komshipData.ajax_url,
                            method: 'GET',
                            dataType: 'json',
                            delay: 500, 
                            data: function(params) {
                                return {
                                    action: 'search_zip_code',
                                    keyword: params.term ,
                                    nonce: komshipData.nonce
                                };
                            },
                            processResults: function(data) {
                                var results = data || [];
                                return {
                                    results: results.map(function(item) {
                                        return {
                                            id: JSON.stringify(item), 
                                            text: item.label 
                                        };
                                    })
                                };
                            },
                            cache: true
                        },
                        escapeMarkup: function(markup) {
                            return markup; 
                        },
                        placeholder: 'Cari kode pos...', 
                    });
                }

                // Initialize the selectWoo dropdown for billing and shipping zip code fields
                initializeZipCodeSelect('#billing_postcode');
                initializeZipCodeSelect('#shipping_postcode');
                initializeZipCodeSelect('#postcode_dokan');
            });
        </script>
        <style>
            .zip-code-results {
                display: none;
                border: 1px solid #ccc;
                background: #fff;
                max-height: 200px;
                overflow-y: auto;
            }
            .zip-result {
                padding: 5px;
                cursor: pointer;
            }
            .zip-result:hover {
                background-color: #f1f1f1;
            }
        </style>
        <?php
    }
}
