    $komship_postcode = get_user_meta($user_id, 'billing_postcode', true);
    $komship_postcode_id = get_user_meta($user_id, 'komship_billing_id', true);
    
    // Initialize options array with default option
    $options = array(
        '' => __('Pilih kode pos', 'pok')
    );
    
    // Prepare saved value
    $saved_value = '';
    
    // Add existing postcode to options if available
    if (!empty($komship_postcode) && !empty($komship_label)) {
        $postcode_data = array(
            'id' => $komship_postcode_id,
            'zip_code' => $komship_postcode,
            'label' => $komship_label
        );
        
        $json_value = wp_json_encode($postcode_data);
        
        if ($json_value !== false) {
            $options[$json_value] = $komship_label;
            $saved_value = $json_value;
        }
    }

    // Ensure the saved value is used properly
    $fields['billing']['billing_postcode'] = array(
        'label'       => __('Cari kode pos untuk Penagihan', 'pok'),
