        'type'        => 'select',
        'class'       => array(
            'zip-code-field',
            'validate-required',
            // 'init-select2'
        ),
        'options'     => $options,
        'required'    => true,
        'priority'    => 60,
        'default'     => $saved_value,
        'custom_attributes' => array(
            'data-selected' => $saved_value,
        ),
    );

    return $fields;
}
