function save_custom_zip_code_field( $order_id ) {
    global $wpdb; // Access the global database object
    $order = wc_get_order( $order_id ); // Retrieve the order object once

    // Process and save billing postcode and related meta
    if ( ! empty( $_POST['billing_postcode'] ) ) {
        $billing_zip_code = json_decode( sanitize_text_field( wp_unslash( $_POST['billing_postcode'] ) ), true );

        if ( isset( $billing_zip_code['zip_code'] ) ) {
            $order->set_billing_postcode( $billing_zip_code['zip_code'] );
            $order->update_meta_data( 'komship_billing_postcode', $billing_zip_code['zip_code'] );

            // Update wp_wc_order_addresses table for billing address
            $wpdb->update(
                $wpdb->prefix . 'wc_order_addresses',
                [ 'postcode' => $billing_zip_code['zip_code'] ], // Data to update
                [ 'order_id' => $order_id, 'address_type' => 'billing' ], // Where clause
                [ '%s' ], // Data format
                [ '%d', '%s' ] // Where clause format
            );
        }

        if ( isset( $billing_zip_code['id'] ) ) {
            $order->update_meta_data( 'komship_billing_id', $billing_zip_code['id'] );
        }
        if ( isset( $billing_zip_code['label'] ) ) {
            $order->update_meta_data( 'komship_billing_label', $billing_zip_code['label'] );
        }

        if ( is_user_logged_in() ) {
            $user_id = get_current_user_id();
            if ( isset( $billing_zip_code['zip_code'] ) ) {
                update_user_meta( $user_id, 'billing_postcode', $billing_zip_code['zip_code'] );
            }
            if ( isset( $billing_zip_code['id'] ) ) {
                update_user_meta( $user_id, 'komship_billing_id', $billing_zip_code['id'] );
            }
            if ( isset( $billing_zip_code['label'] ) ) {
                update_user_meta( $user_id, 'komship_billing_label', $billing_zip_code['label'] );
            }
        }
    }

    // Handle shipping data
    if ( ! empty( $_POST['shipping_postcode'] ) ) {
        $shipping_zip_code = json_decode( sanitize_text_field( wp_unslash( $_POST['shipping_postcode'] ) ), true );

        if ( isset( $shipping_zip_code['zip_code'] ) ) {
            $order->set_shipping_postcode( $shipping_zip_code['zip_code'] );
            $order->update_meta_data( 'komship_shipping_postcode', $shipping_zip_code['zip_code'] );

            // Update wp_wc_order_addresses table for shipping address
            $wpdb->update(
                $wpdb->prefix . 'wc_order_addresses',
                [ 'postcode' => $shipping_zip_code['zip_code'] ], // Data to update
                [ 'order_id' => $order_id, 'address_type' => 'shipping' ], // Where clause
                [ '%s' ], // Data format
                [ '%d', '%s' ] // Where clause format
            );
        }

        if ( isset( $shipping_zip_code['id'] ) ) {
            $order->update_meta_data( 'komship_shipping_id', $shipping_zip_code['id'] );
        }
        if ( isset( $shipping_zip_code['label'] ) ) {
            $order->update_meta_data( 'komship_shipping_label', $shipping_zip_code['label'] );
        }

        if ( is_user_logged_in() ) {
            $user_id = get_current_user_id();
            if ( isset( $shipping_zip_code['zip_code'] ) ) {
                update_user_meta( $user_id, 'shipping_postcode', $shipping_zip_code['zip_code'] );
            }
            if ( isset( $shipping_zip_code['id'] ) ) {
                update_user_meta( $user_id, 'komship_shipping_id', $shipping_zip_code['id'] );
            }
            if ( isset( $shipping_zip_code['label'] ) ) {
                update_user_meta( $user_id, 'komship_shipping_label', $shipping_zip_code['label'] );
            }
        }
    }

    // Ensure shipping data matches billing data if not set separately
    if ( empty( $_POST['ship_to_different_address'] ) || $_POST['ship_to_different_address'] !== '1' ) {
        $billing_postcode = $order->get_billing_postcode();
        $order->set_shipping_postcode( $billing_postcode );

        $order->update_meta_data( 'komship_shipping_postcode', $billing_postcode );

        // Sync shipping postcode in wc_order_addresses table
        $wpdb->update(
            $wpdb->prefix . 'wc_order_addresses',
            [ 'postcode' => $billing_postcode ], // Data to update
            [ 'order_id' => $order_id, 'address_type' => 'shipping' ], // Where clause
            [ '%s' ], // Data format
            [ '%d', '%s' ] // Where clause format
        );

        if ( is_user_logged_in() ) {
            $user_id = get_current_user_id();
            update_user_meta( $user_id, 'shipping_postcode', $billing_postcode );
        }
    }

    $order->save();
}
add_action( 'woocommerce_checkout_update_order_meta', 'save_custom_zip_code_field', 20 );


function custom_checkout_zip_code_validation() {
    
    if ( is_virtual_cart() ) {
        return;
    }
    // Check if billing zip code is required
    if ( ! isset( $_POST['billing_postcode'] ) || empty( $_POST['billing_postcode'] ) ) {
        wc_add_notice( __( 'Kode Pos Penagihan harus diisi' ), 'error' );
    }

    // Check if shipping zip code is required only when "Ship to a different address" is checked
    if ( isset( $_POST['ship_to_different_address'] ) && $_POST['ship_to_different_address'] == 1 ) {
        if ( ! isset( $_POST['shipping_postcode'] ) || empty( $_POST['shipping_postcode'] ) ) {
            wc_add_notice( __( 'Kode Pos Pengiriman harus diisi.' ), 'error' );
        }
    }
}
add_action( 'woocommerce_checkout_process', 'custom_checkout_zip_code_validation' );

// Action hook to handle AJAX request
function handle_zip_code_search() {
    $keyword = isset($_GET['keyword']) ? sanitize_text_field($_GET['keyword']) : '';
    
    if (empty($keyword)) {
        echo json_encode([]);
        wp_die();
    }

    // API URL and headers
    $api_url = 'https://api.collaborator.komerce.my.id/tariff/api/v1/destination/search?keyword=' . urlencode($keyword);
    $response = wp_remote_get($api_url, [
        'headers' => [
            'x-api-key' => 'hTw1KOHi1ec5f64b3678ff10YfDvFDyV',
        ]
    ]);

    if (is_wp_error($response)) {
        echo json_encode([]);
    } else {
        $body = wp_remote_retrieve_body($response);
        $data = json_decode($body, true);
        echo json_encode($data['data']); // Send only the 'data' part
    }

    wp_die();
}

// Register the AJAX action for both logged-in and non-logged-in users
add_action('wp_ajax_search_zip_code', 'handle_zip_code_search');
add_action('wp_ajax_nopriv_search_zip_code', 'handle_zip_code_search');


