// ASURANSI PLUGIN ONGKOS KIRIM
add_filter('pok_set_insurance', function($insurance, $courier, $total) {


    switch ($courier) {
        case 'jne':
            $insurance = (0.002 * $total) + 5000;
            break;
        case 'sicepat':
            if ($total > 500000) {
                $insurance = 0.003 * $total;
            } else {
                $insurance = 0;
            }
            break;
        case 'idexpress':
            $insurance = 0.002 * $total;
            break;
        case 'sap':
            $insurance = (0.003 * $total) + 2000; 
            break;
        case 'ninja':
            $insurance = ($total <= 1000000) ? 2500 : (0.0025 * $total);
            break;
        case 'jnt':
            $insurance = 0.002 * $total;
            break;
        default:
            $insurance = $insurance; 
            break;
    }

    return round($insurance);
}, 10, 3);

add_action('dokan_checkout_update_order_meta', 'fix_dokan_suborder_shipping', 10, 1);

function fix_dokan_suborder_shipping($main_order_id) {
    $main_order = wc_get_order($main_order_id);

    if (!$main_order) {
        return; // Ensure the main order exists before proceeding
    }

    // Retrieve custom zip code fields from the main order
    $billing_zip_code = [
        'zip_code' => $main_order->get_meta('komship_billing_postcode'),
        'id'       => $main_order->get_meta('komship_billing_id'),
        'label'    => $main_order->get_meta('komship_billing_label'),
    ];
    $shipping_zip_code = [
        'zip_code' => $main_order->get_meta('komship_shipping_postcode'),
        'id'       => $main_order->get_meta('komship_shipping_id'),
        'label'    => $main_order->get_meta('komship_shipping_label'),
    ];

    // Check if the main order has sub-orders
    $sub_order_ids = get_post_meta($main_order_id, 'dokan_sub_order_ids', true);

    if (!empty($sub_order_ids) && is_array($sub_order_ids)) {
        foreach ($sub_order_ids as $sub_order_id) {
            $sub_order = wc_get_order($sub_order_id);

            if (!$sub_order) {
                continue; // Skip if sub-order doesn't exist
            }

            // Update billing metadata in the sub-order
            $sub_order->update_meta_data('komship_billing_postcode', $billing_zip_code['zip_code']);
            $sub_order->update_meta_data('komship_billing_id', $billing_zip_code['id']);
            $sub_order->update_meta_data('komship_billing_label', $billing_zip_code['label']);
            $sub_order->set_billing_postcode($billing_zip_code['zip_code']);

            // Update shipping metadata in the sub-order
            $sub_order->update_meta_data('komship_shipping_postcode', $shipping_zip_code['zip_code']);
            $sub_order->update_meta_data('komship_shipping_id', $shipping_zip_code['id']);
            $sub_order->update_meta_data('komship_shipping_label', $shipping_zip_code['label']);
            $sub_order->set_shipping_postcode($shipping_zip_code['zip_code']);

            // Copy billing and shipping addresses from main order
            $sub_order->set_billing($main_order->get_address('billing'));
            $sub_order->set_shipping($main_order->get_address('shipping'));

            // Copy shipping methods
            $main_shipping_items = $main_order->get_items('shipping');
            $sub_shipping_items = $sub_order->get_items('shipping');

            // Clear existing shipping items in sub-order to avoid duplicates
            foreach ($sub_shipping_items as $sub_shipping_item_id => $sub_shipping_item) {
                $sub_order->remove_item($sub_shipping_item_id);
            }

            // Add shipping items from main order to sub-order
            foreach ($main_shipping_items as $shipping_item) {
                $new_shipping_item = clone $shipping_item; // Clone to avoid reference issues
                $sub_order->add_item($new_shipping_item);
            }

            // Recalculate totals for the sub-order
            $sub_order->calculate_totals();
            $sub_order->save();
        }
    }
}



// Define the custom filter for accepted order statuses
add_filter( 'tpc_accepted_order_status', 'add_waiting_confirm_order_status', 10, 1 );

function add_waiting_confirm_order_status( $statuses ) {
    
    if ( ( $key = array_search( 'waiting-confirm', $statuses ) ) !== false ) {
        unset( $statuses[$key] );
    }
    
    return $statuses;
}


