// Tambahkan di functions.php atau file plugin kustom

// Tambahkan rewrite rule
add_action('init', 'tambah_webhook_endpoint');
function tambah_webhook_endpoint() {
    add_rewrite_rule(
        '^webhook/?$', 
        'index.php?webhook=1', 
        'top'
    );
    
    // Tambahkan query var
    add_rewrite_tag('%webhook%', '([^&]+)');
}

// Tangani request webhook
add_action('template_redirect', 'proses_webhook_request');
function proses_webhook_request() {
    $webhook = get_query_var('webhook');
    
    if ($webhook == 1) {
        // Pastikan hanya menerima POST
        if ($_SERVER['REQUEST_METHOD'] === 'POST') {
            // Ambil raw data
            $raw_data = file_get_contents('php://input');
            $data = json_decode($raw_data, true);

            // Validasi data
            if ($data) {
                // Proses data
                webhook_simpan_data($data);
                
                // Kirim respons
                wp_send_json_success('Data webhook diterima');
                exit;
            }

            // Jika data tidak valid
            wp_send_json_error('Data webhook tidak valid', 400);
            exit;
        }
    }
}

// Fungsi untuk menyimpan data webhook
function webhook_simpan_data($data) {
    // Contoh: Simpan ke post type khusus
    $post_id = wp_insert_post([
        'post_type' => 'webhook_log',
        'post_title' => 'Webhook Data ' . date('Y-m-d H:i:s'),
        'post_content' => json_encode($data),
        'post_status' => 'publish'
    ]);

    // Simpan metadata tambahan jika diperlukan
    if ($post_id) {
        update_post_meta($post_id, 'webhook_source_ip', $_SERVER['REMOTE_ADDR']);
        update_post_meta($post_id, 'webhook_raw_data', $data);
    }

    // Log untuk debugging
    error_log('Webhook Data Diterima: ' . print_r($data, true));
}

// Aktifkan flush rewrite rules (jalankan sekali)
register_activation_hook(__FILE__, 'webhook_rewrite_flush');
function webhook_rewrite_flush() {
    tambah_webhook_endpoint();
    flush_rewrite_rules();
}


add_action('cb_notif', 'add_name_to_registered_member', 99, 2);

function add_name_to_registered_member($id_user, $action) {
    global $wpdb;

    // Log to confirm if the action is triggered
    error_log('MASUK KE ACTION CB NOTIF REGISTRASI');

    if ($action === 'registrasi') {
        
        error_log("Received ID_USER: " . $id_user);
        error_log("Received ACTION: " . $action);
        
        $member = $wpdb->get_row(
            $wpdb->prepare(
                "SELECT nama, idwp FROM wp_member WHERE id_user = %d",
                $id_user
            )
        );
        
        // Log the SQL query result
        if ($member) {
            error_log("Member data found: " . print_r($member, true));
        } else {
            error_log("No member data found for user ID: " . $id_user);
        }

        // If member data exists
        if ($member) {
            $wp_user_id = $member->idwp;

            // Log the WordPress user ID
            error_log("WordPress User ID: " . $wp_user_id);

            // Log the member name before updating
            error_log("Member name: " . $member->nama);

           
            $update_first_name = update_user_meta($wp_user_id, 'first_name', $member->nama);
            
            // Log whether the update was successful
            if ($update_first_name) {
                error_log("Successfully updated first_name for user ID: " . $wp_user_id);
            } else {
                error_log("Failed to update first_name for user ID: " . $wp_user_id);
            }

            // Optionally, log the last name update (if applicable)
            // $update_last_name = update_user_meta($wp_user_id, 'last_name', $last_name);
            // error_log("Last name update: " . ($update_last_name ? "Success" : "Failed"));
        } else {
            error_log("No member found for ID_USER: " . $id_user);
        }
    }
}

