function display_product_categories_clean_shortcode() {
    // Mendapatkan semua kategori produk
    $args = array(
        'taxonomy'   => 'product_cat',
        'orderby'    => 'name',
        'order'      => 'ASC',
        'hide_empty' => true,
        'parent'     => 0, // Only top-level categories
    );
    $categories = get_terms($args);
    if (empty($categories) || is_wp_error($categories)) {
        return '<p>No categories found.</p>';
    }
    
    // Memulai output HTML
    $output = '<div class="product-categories-grid-accordion flat-design">';
    $is_member = get_user_meta(get_current_user_id(), 'shopbiz_user_id', true);

    if($is_member){
        $output .= do_shortcode('[ppob_button]');
    }
    

    foreach ($categories as $category) {
        // Get subcategories
        $subcategories = get_terms([
            'taxonomy' => 'product_cat',
            'parent' => $category->term_id,
            'hide_empty' => true,
        ]);
        if($category->name === 'Uncategorized') {
			continue;
		}
		
        $output .= '<div class="category-grid-item">';
        $output .= '<div class="category-header">';
        $output .= '<a href="' . esc_url(get_term_link($category)) . '" class="category-main-link">';
        $output .= esc_html($category->name);
        $output .= ' <span class="category-count">(' . intval($category->count) . ')</span>';
        $output .= '</a>';
        
        // Add expand button only if there are subcategories
        if (!empty($subcategories)) {
            $output .= '<button class="category-expand-btn" aria-label="Expand Category">';
            $output .= '<span class="expand-icon">+</span>';
            $output .= '</button>';
        }
        
        $output .= '</div>';
        
        // Subcategories section
        if (!empty($subcategories)) {
            $output .= '<div class="category-subcategories">';
            $output .= '<ul>';
            foreach ($subcategories as $subcategory) {
                $output .= '<li>';
                $output .= '<a href="' . esc_url(get_term_link($subcategory)) . '">';
                $output .= esc_html($subcategory->name);
                $output .= ' <span class="subcategory-count">(' . intval($subcategory->count) . ')</span>';
                $output .= '</a>';
                $output .= '</li>';
            }
            $output .= '</ul>';
            $output .= '</div>';
        }
        
        $output .= '</div>';
    }
    $output .= '</div>';
    
    // Tambahkan CSS untuk flat design dengan darkorange aksen
    $output .= '<style>
        .product-categories-grid-accordion.flat-design {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 15px;
            padding: 20px 0;
        }
