// Fungsi untuk mengecek produk afiliasi dan saldo vendor
function check_affiliate_product_and_vendor_balance($passed, $product_id) {
    // Mengecek apakah produk adalah produk afiliasi
    $is_affiliate_product = get_post_meta($product_id, '_is_affiliate_product', true);
    
    if ($is_affiliate_product === 'yes') {
        // Mendapatkan vendor ID dari post_author (penulis produk)
        $vendor_id = get_post_field('post_author', $product_id);
        
        if ($vendor_id) {
            // Mendapatkan saldo vendor untuk tipe poin 'point_seller_internal'
            $balance = mycred_get_users_balance($vendor_id, 'point_seller_internal');
            
            // Mengecek apakah saldo vendor cukup (lebih besar dari 0)
            if ($balance <= 0) {
                // Jika saldo vendor 0 atau negatif, menampilkan pesan dan mencegah produk ditambahkan ke keranjang
                wc_add_notice(__('Silahkan hubungi vendor untuk informasi produk ini.', 'text-domain'), 'error');
                return false; // Menghentikan proses checkout atau penambahan produk ke keranjang
            }
        }
    }
    
    return $passed; 
}
add_filter('woocommerce_add_to_cart_validation', 'check_affiliate_product_and_vendor_balance', 100, 2);
// add_filter('woocommerce_checkout_process', 'check_affiliate_product_and_vendor_balance', 100, 2);
// Add custom script to disable Add to Cart button on single product page
function disable_add_to_cart_button_for_affiliate_products_on_product_page() {
    global $product;

    // Check if we're on a single product page
    if (is_product() && $product) {
        // Check if the current product is an affiliate product
        $is_affiliate_product = get_post_meta($product->get_id(), '_is_affiliate_product', true);

        if ($is_affiliate_product === 'yes') {
            // Get vendor ID from post author (author of the product)
            $vendor_id = get_post_field('post_author', $product->get_id());

            if ($vendor_id) {
                // Get vendor's balance for the 'point_seller_internal' point type
                $balance = mycred_get_users_balance($vendor_id, 'point_seller_internal');

                // If the balance is insufficient (0 or negative), disable the button
                if ($balance <= 0) {
                    ?>
                    <script type="text/javascript">
                        jQuery(function($) {
                            // Disable the Add to Cart button
                            $('button.single_add_to_cart_button').prop('disabled', true).addClass('disabled').text('Produk tidak aktif');
                        });
                    </script>
                    <?php
                }
            }
        }
    }
}
add_action('wp_footer', 'disable_add_to_cart_button_for_affiliate_products_on_product_page');

