function search_products() {
    $query = isset($_POST['query']) ? sanitize_text_field($_POST['query']) : '';
    $args = [
        'post_type' => 'product',
        'posts_per_page' => 5,
        's' => $query,
    ];
    $products = new WP_Query($args);

    if ($products->have_posts()) {
        while ($products->have_posts()) {
            $products->the_post();
            $product = wc_get_product(get_the_ID()); ?>
            <a href="<?php the_permalink(); ?>">
                <?php echo $product->get_image(); ?>
                <div class="product-title"><?php the_title(); ?></div>
                <div class="product-price"><?php echo $product->get_price_html(); ?></div>
            </a>
        <?php }
    } else {
        echo '<div class="no-results">Produk tidak ditemukan</div>';
    }

    wp_reset_postdata();
    wp_die();
}
add_action('wp_ajax_search_products', 'search_products');
add_action('wp_ajax_nopriv_search_products', 'search_products');

function add_poin_level_affiliate_before_order_table( $order ) {
    // Get order ID
    $order_id = $order->get_id();

    // Get order items
    $order_items = $order->get_items();

    // Retrieve poin_level_affiliate data for the order
    $poin_level_affiliate_data = get_post_meta( $order_id, 'poin_level_affiliate', true );
    $poin_level_affiliate_data = is_array( $poin_level_affiliate_data ) ? $poin_level_affiliate_data : [];

    // Initialize total point level
    $total_point_level = 0;

    echo '<h3>' . __( 'Poin Level Yang Didapatkan dari Produk', 'your-textdomain' ) . '</h3>';
    echo '<table class="shop_table shop_table_responsive">';

    // Display a header for the table
    echo '<thead>
            <tr>
                <th>' . __( 'Product', 'your-textdomain' ) . '</th>
                <th>' . __( 'Poin Level', 'your-textdomain' ) . '</th>
                <th>' . __( 'Estimasi', 'your-textdomain' ) . '</th>
            </tr>
          </thead>';
    echo '<tbody>';

    // Loop through order items
    $index = 0;
    foreach ( $order_items as $item ) {
        // Get product details
        $product = $item->get_product();

        if ( ! $product ) {
            continue; // Skip if product is not found
        }

        $product_name = $product->get_name();
        $product_id = $product->get_id();
        $variation_id = $item->get_variation_id();
        $effective_product_id = $variation_id ? $variation_id : $product_id;

        // Initialize point level and estimation
        $point_level = 0;
        $point_estimation = '-';

        // Quantity of the product
        $quantity = $item->get_quantity();

        // Check if the product is an affiliate product using the custom metadata '_is_affiliate_product'
        $is_affiliate_product = get_post_meta( $product_id, '_is_affiliate_product', true );

        if ( $is_affiliate_product == 'yes' ) {
            // Affiliate product logic
            $point_level = (float) ( isset( $poin_level_affiliate_data[ $index ] ) ? $poin_level_affiliate_data[ $index ] : 0 );

            // Fetch point estimation for affiliate products
            $point_estimation_meta = get_post_meta( $effective_product_id, 'point_reward_estimation', true );
            $point_estimation = ! empty( $point_estimation_meta ) ? (float) $point_estimation_meta : 0;

            // Multiply point estimation by quantity for affiliate products
            $point_estimation *= $quantity;
        } else {
            // Non-affiliate product logic (Simple or Variable)
            $reward_meta_key = $variation_id ? '_mycred_reward' : 'mycred_reward';
            $product_point = get_post_meta( $effective_product_id, $reward_meta_key, true );
            $point_level = isset( $product_point['point_level'] ) ? (float) $product_point['point_level'] : 0;

            // Multiply points by quantity for non-affiliate products
            $point_level *= $quantity;
        }

        // Add points to total
        $total_point_level += $point_level;

        // Output product details
        echo '<tr>';
        echo '<td>' . esc_html( $product_name  ) . '<strong>'. ' x' . $quantity .'</strong>' .'</td>';
        echo '<td>' . esc_html( number_format( $point_level ) ) . '</td>';
        echo '<td>' . esc_html(  $point_estimation ) . '</td>';
        echo '</tr>';

        $index++;
    }

    echo '</tbody>';
    echo '</table>';

    // Check if the order is completed
    if ( $order->get_status() === 'completed' ) {
        // Display total points if applicable
        if ( $total_point_level > 0 ) {
            echo '<p><strong>' . __( 'Total Poin Level:', 'your-textdomain' ) . '</strong> ' . esc_html( number_format( $total_point_level ) ) . '</p>';
        }
    } else {
        echo '<p>' . __( 'Point belum terkirim, total point ditampilkan jika pesanan telah selesai', 'your-textdomain' ) . '</p>';
    }
}
add_action( 'woocommerce_order_details_before_order_table', 'add_poin_level_affiliate_before_order_table' );
// add_action( 'woocommerce_order_details_before_order_table', 'add_poin_level_affiliate_before_order_table' );
function show_estimation_point_level_shortcode() {
    // Access the WooCommerce cart
    $cart = WC()->cart;
    if (!$cart) {
        return ''; // Return empty string if the cart is not available
    }

    $total_points = 0;
    $has_affiliate_product = false; // Flag to check if there is any affiliate product

    // Iterate through cart items to calculate total estimation points
    foreach ($cart->get_cart() as $cart_item) {
        $product_id = $cart_item['product_id']; // Get the product ID
        $qty = $cart_item['quantity']; // Get the quantity in the cart

        // Check if the product is an affiliate product
        $is_affiliate = get_post_meta($product_id, '_is_affiliate_product', true);

        // If the product is an affiliate product, we flag it
        if ($is_affiliate === 'yes') {
            $has_affiliate_product = true;

            // Get the estimated points for the product from post meta
            $point_reward_estimation = get_post_meta($product_id, 'point_reward_estimation', true);

            // Ensure the point estimation is a valid number
            if (is_numeric($point_reward_estimation)) {
                $total_points += $point_reward_estimation * $qty; // Add to the total points
            }
        }
    }

    // If there are no affiliate products, don't show the message
    if (!$has_affiliate_product) {
        return ''; // Return empty string if no affiliate products in the cart
    }

    // Build the output HTML for the affiliate products
    $output = '<div id="yith-par-message-checkout" class="woocommerce-checkout-notice woocommerce-info" style="display: flex; justify-content: space-between; align-items: center;">';
    $output .= '<div>';
    $output .= '<img decoding="async" style="max-width: 35px; margin-right: 5px;" src="https://shopbiz.id/wp-content/plugins/yith-woocommerce-points-and-rewards-premium/assets/images/prize.svg">';
    $output .= 'Setelah pesanan selesai, kamu akan mendapatkan hingga &nbsp;<strong>' . esc_html($total_points) . '</strong> Point Level dari pembelian produk affiliate ini!';
    $output .= '</div>';
    $output .= '</div>';

    return $output; // Return the output to be displayed in the shortcode
}

// Register the shortcode
add_shortcode('show_estimation_point_level', 'show_estimation_point_level_shortcode');

function show_estimation_point_level_checkout(){
    echo do_shortcode('[show_estimation_point_level]');
}

