// Simpan nilai meta saat halaman disimpan
function save_is_campaign_meta_box($post_id) {
    // Cek apakah user memiliki izin untuk mengedit post
    if (!current_user_can('edit_post', $post_id)) {
        return;
    }

    // Cek apakah input meta sudah diset
    if (isset($_POST['is_campaign_page'])) {
        // Sanitasi dan simpan meta
        $value = sanitize_text_field($_POST['is_campaign_page']);
        update_post_meta($post_id, '_is_campaign_page', $value);
    } else {
        // Hapus meta jika tidak diisi
        delete_post_meta($post_id, '_is_campaign_page');
    }
	
	// Simpan WhatsApp Caption
    if (isset($_POST['whatsapp_caption'])) {
        $whatsapp_caption = sanitize_text_field($_POST['whatsapp_caption']);
        update_post_meta($post_id, '_whatsapp_caption', $whatsapp_caption);
    } else {
        delete_post_meta($post_id, '_whatsapp_caption');
    }
}
