// Shortcode untuk menampilkan daftar halaman dengan is_campaign_page = yes
function show_campaign_pages_shortcode($atts) {
    global $wpdb;

    // Query campaign pages dengan meta_key _is_campaign_page = yes
    $query = new WP_Query([
        'post_type'      => 'page',
        'meta_key'       => '_is_campaign_page',
        'meta_value'     => 'yes',
        'posts_per_page' => -1,
        'orderby'        => 'title',
        'order'          => 'ASC',
    ]);

    // Jika tidak ada halaman kampanye
    if (!$query->have_posts()) {
        return '<p>Tidak ada halaman kampanye ditemukan.</p>';
    }

    $output = '<h2 class="blog-posts-section-title">Landing Page</h2>';
    $output .= '<div class="campaign-pages-list">';

    while ($query->have_posts()) {
        $query->the_post();

        // Ambil data halaman
        $page_title   = get_the_title();
        $page_url     = get_permalink();
        $page_preview = wp_get_attachment_image_src(get_post_thumbnail_id(), 'medium');
        $whatsapp_caption = get_post_meta(get_the_ID(), '_whatsapp_caption', true); // Ambil caption WhatsApp
        $user_id      = get_current_user_id();
        $sponsor      = '';
        $final_url    = $page_url; // Default URL (tidak ditambahkan caption)

        // Jika user login, tambahkan sponsor ke URL
        if ($user_id) {
            $sponsor = $wpdb->get_var($wpdb->prepare("SELECT subdomain FROM wp_member WHERE idwp = %d", $user_id));
            if ($sponsor) {
                $final_url = add_query_arg('reg', $sponsor, $page_url);
            }
        }

        // Menampilkan data
        $output .= '<div class="campaign-page-card">';
        if ($page_preview) {
            $output .= '<div class="campaign-page-preview">
                            <img src="' . esc_url($page_preview[0]) . '" alt="' . esc_attr($page_title) . '">
                        </div>';
        }
        $output .= '<div class="campaign-page-info">
                        <h3><a href="' . esc_url($final_url) . '">' . esc_html($page_title) . '</a></h3>
                        <a href="' . esc_url($final_url) . '" class="campaign-page-link">Kunjungi Halaman</a><br>
                        <button class="whatsapp-share-btn" data-url="' . esc_url($final_url) . '" data-caption="' . esc_attr($whatsapp_caption) . '">Bagikan ke WhatsApp</button>
                    </div>';
        $output .= '</div>';
    }

    wp_reset_postdata();
    $output .= '</div>';

    // JavaScript untuk menangani klik tombol
    $output .= '<script>
        document.addEventListener("DOMContentLoaded", function() {
            document.querySelectorAll(".whatsapp-share-btn").forEach(function(button) {
                button.addEventListener("click", function() {
                    const url = this.getAttribute("data-url");
                    const caption = this.getAttribute("data-caption") || "";
                    const fullMessage = caption ? caption + "\n\n" + url : url;
                    const whatsappLink = "whatsapp://send?text=" + encodeURIComponent(fullMessage);
                    window.location.href = whatsappLink;
                });
            });
        });
    </script>';

    return $output;
}
