function show_blog_posts_shortcode($atts) {
    global $wpdb;

    // Definisikan atribut shortcode
    $atts = shortcode_atts(
        array(
            'category'       => '',  // Default kategori kosong (slug, bukan array)
            'posts_per_page' => -1,  // Tampilkan semua posting terkait
        ),
        $atts,
        'blog_posts'
    );

    // Konversi slug kategori menjadi ID jika diberikan dalam shortcode
    $category_ids = [];
    if (!empty($atts['category'])) {
        $category_slugs = array_map('trim', explode(',', $atts['category'])); // Support multiple kategori
        foreach ($category_slugs as $slug) {
            $category = get_term_by('slug', $slug, 'category'); // Ambil ID kategori dari slug
            if ($category) {
                $category_ids[] = $category->term_id;
            }
        }
    }

    // Query untuk mengambil posting berdasarkan kategori yang dipilih
    $query_args = [
        'post_type'      => 'post',
        'posts_per_page' => intval($atts['posts_per_page']),
        'orderby'        => 'title',
        'order'          => 'ASC',
    ];

    if (!empty($category_ids)) {
        $query_args['category__in'] = $category_ids;
    }

    $query = new WP_Query($query_args);

    // Jika tidak ada postingan, tampilkan pesan
    if (!$query->have_posts()) {
        return '<p>Tidak ada postingan ditemukan.</p>';
    }

    // Mulai output HTML
    $output = '<div class="blog-posts-section">
                <h2 class="blog-posts-section-title">Blog Posts</h2>
                <div class="blog-posts-list">';

    while ($query->have_posts()) {
        $query->the_post();

        // Ambil data postingan
        $post_title   = get_the_title();
        $post_url     = get_permalink();
        $post_preview = wp_get_attachment_image_src(get_post_thumbnail_id(), 'medium');
        $user_id      = get_current_user_id();
        $sponsor      = '';
        $final_url    = $post_url; // Default URL

        // Jika user login, tambahkan query parameter untuk sponsor
        if ($user_id) {
            $sponsor = $wpdb->get_var($wpdb->prepare("SELECT subdomain FROM wp_member WHERE idwp = %d", $user_id));
            if ($sponsor) {
                $final_url = add_query_arg('reg', $sponsor, $post_url);
            }
        }

        // Tampilkan data dalam bentuk kartu
        $output .= '<div class="blog-post-card">';
        if ($post_preview) {
            $output .= '<div class="blog-post-preview">
                            <img src="' . esc_url($post_preview[0]) . '" alt="' . esc_attr($post_title) . '">
                        </div>';
        }
        $output .= '<div class="blog-post-info">
                        <h3><a href="' . esc_url($final_url) . '">' . esc_html($post_title) . '</a></h3>
                        <a href="' . esc_url($final_url) . '" class="blog-post-link">Kunjungi Postingan</a><br>
                        
                    </div>';
        $output .= '</div>';
		//<button class="whatsapp-share-btn" data-url="' . esc_url($final_url) . '">Bagikan ke WhatsApp</button>
    }

    // Reset query
    wp_reset_postdata();

    $output .= '</div></div>';

    // JavaScript untuk tombol WhatsApp
    $output .= '<script>
        document.addEventListener("DOMContentLoaded", function() {
            document.querySelectorAll(".whatsapp-share-btn").forEach(function(button) {
                button.addEventListener("click", function() {
                    var url = this.getAttribute("data-url");
                    window.location.href = "whatsapp://send?text=" + encodeURIComponent(url);
                });
            });
        });
    </script>';

    return $output;
}
add_shortcode('blog_posts', 'show_blog_posts_shortcode');

