function add_share_and_copy_buttons($content) {
    if (is_single()) {
        global $post, $wpdb;
        
        // Ambil user ID
        $user_id = get_current_user_id();

        // Ambil judul & URL postingan
        $post_title = get_the_title($post->ID);
        $post_url   = get_permalink($post->ID);

        // Tambahkan query parameter 'reg' jika user login dan punya sponsor
        if ($user_id) {
            $sponsor = $wpdb->get_var($wpdb->prepare("SELECT subdomain FROM wp_member WHERE idwp = %d", $user_id));
            if ($sponsor) {
                $post_url = add_query_arg('reg', $sponsor, $post_url);
            }
        }

        // Ambil isi postingan & format teks untuk WhatsApp
        $post_content = strip_tags(get_the_content($post->ID));
        $whatsapp_text = "*$post_title*\n\n$post_content\n\n🔗 Baca selengkapnya: $post_url";

        // Tombol WhatsApp & Copy
        $buttons = '<div style="margin-top: 20px; display: flex; gap: 10px; flex-wrap: wrap;">';
        
        // Tombol Bagikan ke WhatsApp
        $buttons .= '<button class="whatsapp-share-btn" style="display: inline-flex; align-items: center; padding: 8px 12px; background-color: #25D366; color: #fff; border: none; border-radius: 5px; cursor: pointer;"
                        data-content="' . esc_attr($whatsapp_text) . '">
                        <img src="https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg" width="24" height="24" alt="WhatsApp" style="margin-right: 5px;"> 
                        Bagikan ke WhatsApp
                    </button>';

        // Tombol Salin Konten
        $buttons .= '<button class="copy-content-btn" style="display: inline-flex; align-items: center; padding: 8px 12px; background-color: #007bff; color: #fff; border: none; border-radius: 5px; cursor: pointer;" 
		data-content="' . esc_attr($whatsapp_text) . '"> 
		📋 Salin Konten 
		</button>';
        
        $buttons .= '</div>';

        // Tambahkan JavaScript untuk berbagi ke WhatsApp & Salin Konten
        $buttons .= '<script>
            document.addEventListener("DOMContentLoaded", function() {
                // Fungsi Salin Konten
                document.querySelectorAll(".copy-content-btn").forEach(function(button) {
                    button.addEventListener("click", function() {
                        const textToCopy = this.getAttribute("data-content");
                        const tempTextArea = document.createElement("textarea");
                        tempTextArea.value = textToCopy;
                        document.body.appendChild(tempTextArea);
                        tempTextArea.select();
                        document.execCommand("copy");
                        document.body.removeChild(tempTextArea);
                        alert("Konten berhasil disalin!");
                    });
                });

                // Fungsi Bagikan ke WhatsApp
                document.querySelectorAll(".whatsapp-share-btn").forEach(function(button) {
                    button.addEventListener("click", function() {
                        const textToShare = this.getAttribute("data-content");
                        const whatsappUrl = "whatsapp://send?text=" + encodeURIComponent(textToShare);
                        window.location.href = whatsappUrl;
                    });
                });
            });
        </script>';

        // Tambahkan tombol ke akhir konten
        $content .= $buttons;
    }
    return $content;
}
add_filter('the_content', 'add_share_and_copy_buttons');

