function affiliator_withdraw_shortcode() {
    if (!is_user_logged_in()) {
        return '<p style="color: red; font-weight: bold;">Silakan login untuk mengajukan withdraw.</p>';
    }

    global $wpdb;
    $user_id = get_current_user_id();
    $user_data = $wpdb->get_row($wpdb->prepare("SELECT * FROM `wp_member` WHERE `idwp` = %d", $user_id));

    if (!$user_data) {
        return '<p style="color: red;">Data tidak ditemukan.</p>';
    }

    if(!isset($user_data->bank) && !isset($user_data->rekening)){
        return '<p style="color: red;">Harap isi terlebih dahulu data Bank dan No. Rekening Anda di Profil</p>';
    }
    $saldo = $user_data->sisa_voucher;
    $output = '<div style="max-width: 100%; margin: auto; border-radius: 8px; ">';
    // <strong style="color: red;">(Dalam Pemeliharaan)</strong></h2>'
    $output .= '<h2 style="text-align: center; color: #333;">Request Withdraw';
    $output .= '<p style="text-align: center; font-size: 16px;">Saldo Anda: <strong style="color: green;">Rp. ' . number_format($saldo) . '</strong></p>';

    if (isset($_POST['request_withdraw']) && is_numeric($_POST['amount'])) {
        $amount = intval(str_replace('.', '', $_POST['amount']));
        if ($amount > 0 && $amount <= $saldo) {
            $options = get_option('xendit_payment_settings');
            $fee = isset($options['fee']) ? esc_attr($options['fee']) : 10000;
            $total_ammount = $amount + $fee;
            $wpdb->insert('cb_withdraw_requests', [
                'user_id' => $user_id,
                'reference_id' => 'SHOPBIZ-WD-' . $user_id . '-' . time(),
                'amount' => $amount,
                'status' => 'pending',
                'fee' => $fee,
                'total_amount' => $total_ammount,
                'payment_method' => $user_data->bank,
                'account_number' => $user_data->rekening,
                'created_at' => current_time('mysql', 1),
            ]);
            $wpdb->query($wpdb->prepare(
                "UPDATE wp_member
                 SET sisa_voucher = GREATEST(sisa_voucher - %d, 0) 
                 WHERE idwp = %d",
                 $total_ammount, $user_id
            ));
            $output .= '<p style="color: green; font-weight: bold; text-align: center;">Withdraw sebesar Rp. ' . number_format($amount) . ' telah diajukan.</p>';
            wp_redirect(home_url('/withdraw'));
            exit;
        } else {
            $output .= '<p style="color: red; font-weight: bold; text-align: center;">Jumlah withdraw tidak valid.</p>';
        }
       
    }
    $options = get_option('xendit_payment_settings');
    $fee = isset($options['fee']) ? esc_attr($options['fee']) : 10000;
    $output .= '<form method="post" style="text-align: center; margin-top: 20px;">';
    $output .= '<label for="amount" style="display: block; font-size: 14px; margin-bottom: 8px;">Jumlah Withdraw:</label>';
    $output .= '<input type="text" name="amount" min="50000" max="' . ($saldo - $fee) . '" required style="padding: 8px; width: 100%; border-radius: 5px; border: 1px solid #ccc; margin-bottom: 10px;" id="withdraw-amount">';
    $output .= '<script>
        document.addEventListener("DOMContentLoaded", function() {
            const amountInput = document.getElementById("withdraw-amount");

            amountInput.addEventListener("input", function() {
                let value = this.value.replace(/\D/g, "");
                this.value = new Intl.NumberFormat("id-ID", {
                    style: "decimal",
                    minimumFractionDigits: 0
                }).format(value);
            });

            document.querySelector("form").addEventListener("submit", function() {
                amountInput.value = amountInput.value.replace(/\D/g, "");
                amountInput.value = amountInput.value.replace(/,/g, "");
            });
        });
    </script>';
    $output .= '<br>';
    $output .= '<input type="submit" name="request_withdraw" value="Ajukan Withdraw" style="background: darkorange; color: white; border: none; padding: 10px 20px; border-radius: 5px; font-size: 16px;">';
    $output .= '<div id="loading-animation" style="display: none; margin-top: 10px;">
                    <img src="https://i.gifer.com/ZZ5H.gif" alt="Loading..." style="width: 50px; height: 50px;">
                </div>';
    $output .= '<script>
                    document.querySelector("form").addEventListener("submit", function() {
