function insert_commission_log($user_id, $commission_provider_type, $commission_type, $reference, $amount, $amount_type, $status) {
    global $wpdb;

    // Pastikan status hanya 'success' atau 'failed'
    if (!in_array($status, ['success', 'failed'])) {
        return new WP_Error('invalid_status', 'Status must be either "success" or "failed".');
    }

    // Tabel WordPress
    $table_name = $wpdb->prefix . 'commission_logs';

    // Query Insert
    $result = $wpdb->insert(
        $table_name,
        [
            'user_id'                  => $user_id,
            'commission_provider_type' => $commission_provider_type,
            'commission_type'          => $commission_type,
            'reference'                => $reference,
            'amount'                   => $amount,
            'amount_type'              => $amount_type,
            'status'                   => $status,
            'created_at'               => current_time('mysql'),
            'updated_at'               => current_time('mysql'),
        ],
        [
            '%d', '%s', '%s', '%s', '%f', '%s', '%s', '%s', '%s'
        ]
    );

    // Cek apakah berhasil
    if ($result === false) {
        return false;
    }

    return true;
}

