function shortcode_challenge_timer($atts) {
    if (!is_user_logged_in()) {
        return '<p style="text-align: center;">You need to be logged in to see this.</p>';
    }

    // Get user data
    $user_id = get_current_user_id();
    $user_data = get_userdata($user_id);
    $registered_date_utc = strtotime($user_data->user_registered); // UTC time

    // Shortcode attributes
    $atts = shortcode_atts([
        'url'   => '#',
        'label' => 'Click Here',
        'color' => '#ff0000' // Default red color
    ], $atts);

    ob_start();
    ?>
    <div style="text-align: center; margin-top: 20px;">
        <!-- Timer Box -->
        <div id="challenge-countdown" style="
            display: inline-block;
            background: <?php echo esc_attr($atts['color']); ?>;
            color: white;
            font-size: 40px;
            font-weight: bold;
            padding: 20px;
            border-radius: 8px;
            margin-bottom: 15px;
            width: 300px;
        ">
            Loading...
        </div>
        <br>

        <!-- Action Button -->
        <a href="<?php echo esc_url($atts['url']); ?>" id="challenge-button" style="
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 12px 24px;
            font-size: 16px;
            color: white;
            background: <?php echo esc_attr($atts['color']); ?>;
            border: none;
            border-radius: 5px;
            text-decoration: none;
            font-weight: bold;
            gap: 8px;
        ">
            ✅ <?php echo esc_html($atts['label']); ?>
        </a>
    </div>

    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
    <script>
        jQuery(document).ready(function($) {
            // Get registered date (UTC) from PHP
            var registeredDateUTC = <?php echo $registered_date_utc; ?> * 1000; // Convert to milliseconds

            // Convert UTC registration date to local time
            var registeredDateLocal = new Date(registeredDateUTC);
            var localTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

            // Convert registered date to local timestamp
            var registeredTimestampLocal = new Date(registeredDateLocal.toLocaleString("en-US", { timeZone: localTimezone })).getTime();

            // Set expiry time (24 hours after registration in local time)
            var expiryTimestampLocal = registeredTimestampLocal + (24 * 60 * 60 * 1000); // Add 24 hours in milliseconds

            // Get current local time
            var currentTimestampLocal = new Date().getTime();
            var remainingTime = Math.floor((expiryTimestampLocal - currentTimestampLocal) / 1000);

            var $timerElement = $("#challenge-countdown");
            var $buttonElement = $("#challenge-button");

            function updateTimer() {
                if (remainingTime <= 0) {
                    $timerElement.html("Time Expired");
                    $buttonElement.hide();
                    return;
                }

                var hours = Math.floor(remainingTime / 3600);
                var minutes = Math.floor((remainingTime % 3600) / 60);
                var seconds = remainingTime % 60;
                $timerElement.html(`${hours}h ${minutes}m ${seconds}s`);
                remainingTime--;

                setTimeout(updateTimer, 1000);
            }

            updateTimer();
        });
    </script>
    <?php
    return ob_get_clean();
}
add_shortcode('challenge_timer', 'shortcode_challenge_timer');

add_action('woocommerce_order_status_completed', 'virans_update_child_coupon_meta_on_order_complete');
function virans_update_child_coupon_meta_on_order_complete($order_id) {
    $order = wc_get_order($order_id);

    if (!$order) return;

    $used_coupons = $order->get_used_coupons(); // array of coupon codes

    if (empty($used_coupons)) return;

    global $wpdb;

    foreach ($used_coupons as $coupon_code) {
        $coupon = new WC_Coupon($coupon_code);
        $parent_coupon_id = $coupon->get_id();

        if (!$parent_coupon_id) continue;

        // Ambil nilai meta poin_level_percentage dari kupon utama
        $poin_level = get_post_meta($parent_coupon_id, 'poin_level_percentage', true);

        if (empty($poin_level)) continue;

        // Cari post anak (kupon yang post_parent = parent_coupon_id)
        $child_coupons = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT ID FROM {$wpdb->posts} WHERE post_parent = %d AND post_type = 'shop_coupon'",
                $parent_coupon_id
            )
        );

        if (empty($child_coupons)) continue;

        // Update poin_level_percentage di setiap kupon anak
        foreach ($child_coupons as $child_coupon) {
            update_post_meta($child_coupon->ID, 'poin_level_percentage', intval($poin_level));
        }
    }
}

function send_notif_dokan_vendor($wa, $message)
{
    $api_url = 'https://tegal.wablas.com/api/send-message';
    $authorization_key = get_option('whatsapp_api_key', '');
    $secret_key = get_option('whatsapp_secret_key', '');

    $response = wp_remote_post($api_url, [
        'headers' => [
            'Authorization' => $authorization_key.'.'.$secret_key,
        ],
        'body' => [
            'phone'   => $wa,
            'message' => $message,
        ],
    ]);

    if (is_wp_error($response)) {
        return false; // Request failed.
    }
}
