// Fungsi cek apakah semua produk di keranjang virtual
function is_virtual_cart() {
    if (WC()->cart && !WC()->cart->is_empty()) {
        foreach (WC()->cart->get_cart() as $cart_item) {
            $product_id = $cart_item['product_id']; // ID Produk
            $is_affiliate = get_post_meta($product_id, '_is_affiliate_product', true);

            if($is_affiliate == 'yes'){
                return true;
            }
            if (!$cart_item['data']->is_virtual()) {
                return false;
            }
            

        }
        return true;
    }
    return false;
}


