// Enqueue JavaScript khusus untuk menyembunyikan field tambahan dari plugin Tonjoo

add_filter( 'woocommerce_checkout_fields', 'disable_required_fields_for_virtual_cart' );
function disable_required_fields_for_virtual_cart( $fields ) {
    if ( is_virtual_cart() ) {
        // Set semua field billing jadi tidak wajib (required)
        foreach ( $fields['billing'] as $key => &$field ) {
            $field['required'] = false;
        }

        // Set semua field shipping juga tidak wajib
        foreach ( $fields['shipping'] as $key => &$field ) {
            $field['required'] = false;
        }
    }

    return $fields;
}

add_filter( 'woocommerce_checkout_fields', 'disable_all_address_validation_virtual' );
function disable_all_address_validation_virtual( $fields ) {
    if ( is_virtual_cart() ) {
        foreach ( $fields['billing'] as $key => &$field ) {
            $field['required'] = false;

            // Hapus semua validasi HTML5 dan plugin (misalnya 'postcode', 'email', dll)
            if ( isset($field['validate']) ) {
                $field['validate'] = [];
            }
        }

        foreach ( $fields['shipping'] as $key => &$field ) {
            $field['required'] = false;
            if ( isset($field['validate']) ) {
                $field['validate'] = [];
            }
        }
    }

    return $fields;
}

add_filter( 'woocommerce_checkout_posted_data', function( $data ) {
    if ( is_virtual_cart() ) {
        $data['billing_postcode'] = ''; // Kosongkan paksa
        $data['shipping_postcode'] = '';
    }
    return $data;
});

add_action( 'woocommerce_after_checkout_validation', function( $data, $errors ) {
    if ( is_virtual_cart() ) {
        // Hapus error yang mengandung kata "kode pos"
        foreach ( $errors->get_error_codes() as $code ) {
            $messages = $errors->get_error_messages( $code );
            foreach ( $messages as $message ) {
                if ( strpos( $message, 'kode pos' ) !== false ) {
                    $errors->remove( $code );
                }
            }
        }
    }
}, 20, 2 );

