    $current_user_id = get_current_user_id();
    $page_id         = isset($_GET['page_id_edit']) ? intval($_GET['page_id_edit']) : 0;

    // Ambil data page
    $page = get_post($page_id);

    if (!$page || $page->post_type !== 'page') {
        return '<p style="color:red;">Halaman tidak ditemukan.</p>';
    }

    // Pastikan user pemilik halaman
    if ((int) $page->post_author !== $current_user_id) {
        return '<p style="color:red;">Anda tidak memiliki akses ke halaman ini.</p>';
    }

    // Proses update form
    if (isset($_POST['update_page'])) {
        $page_title   = sanitize_text_field($_POST['page_title']);
        $page_content = wp_kses_post($_POST['page_content']);

        if (!empty($page_title)) {
            wp_update_post(array(
                'ID'           => $page_id,
                'post_title'   => $page_title,
                'post_content' => $page_content,
            ));

            echo '<div style="padding:10px; background:#d4edda; color:#155724; margin-bottom:10px;">Halaman berhasil diperbarui!</div>';
            // Refresh data
            $page = get_post($page_id);
