// Tambahkan capabilities dasar untuk Elementor pada role 'customer' dan 'subscriber'
function add_elementor_capabilities_to_users() {
    $roles = ['affiliator_user'];

    foreach ($roles as $role_name) {
        $role = get_role($role_name);

        if ($role) {
            // Basic capabilities
            $role->add_cap('read');
            $role->add_cap('upload_files');

            // Page editing
            $role->add_cap('edit_pages');
            $role->add_cap('publish_pages');
            $role->add_cap('delete_pages');
            $role->add_cap('delete_published_pages');
            $role->add_cap('edit_published_pages');
            //$role->add_cap('edit_others_pages');

            // Post editing (needed by Elementor sometimes)
            $role->add_cap('edit_posts');
            $role->add_cap('publish_posts');
            $role->add_cap('delete_posts');
            $role->add_cap('edit_others_posts');

            // Elementor specific
            $role->add_cap('edit_with_elementor');
            $role->add_cap('elementor_edit_page');

            // Optional for full editing flexibility
            $role->add_cap('unfiltered_html');
            
            $role->add_cap('read_private_pages');
            $role->add_cap('edit_private_pages');
            $role->add_cap('edit_draft_pages');
        }
    }
}
add_action('init', 'add_elementor_capabilities_to_users');



