// Shortcode untuk create page dengan redirect ke Elementor
function frontend_create_page_elementor_shortcode() {
    if (!is_user_logged_in() || !current_user_can('publish_pages')) {
        return '<p>Akses ditolak.</p>';
    }

    if (!did_action('elementor/loaded')) {
        return '<p>Elementor tidak aktif.</p>';
    }

    ob_start();

    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['create_page_nonce'])) {
        if (!wp_verify_nonce($_POST['create_page_nonce'], 'create_page_action')) {
            wp_die('Keamanan gagal.');
        }

        $title = sanitize_text_field($_POST['page_title']);
        $page_id = wp_insert_post([
            'post_title'  => $title,
            'post_type'   => 'page',
            'post_status' => 'draft',
            'post_author' => get_current_user_id(),
        ]);

        if ($page_id && !is_wp_error($page_id)) {
            $document = \Elementor\Plugin::instance()->documents->get($page_id);
            if ($document) {
                wp_redirect($document->get_edit_url());
                exit;
            }
        } else {
            echo '<p style="color:red;">Gagal membuat halaman.</p>';
        }
    }
    ?>
    <div class="frontend-page-form">
        <h2>Buat Halaman Baru</h2>
        <form method="post">
            <?php wp_nonce_field('create_page_action', 'create_page_nonce'); ?>
            <div class="form-group">
                <label for="page_title">Judul Halaman</label>
                <input type="text" name="page_title" id="page_title" required class="form-control" placeholder="Masukkan judul halaman">
            </div>
            <button type="submit" class="btn btn-elementor">
                <i class="eicon-elementor"></i> Buat dan Edit di Elementor
            </button>
        </form>
        <a href="<?php echo home_url('/manage-pages'); ?>" class="btn btn-secondary">Kembali</a>
    </div>
    <?php
    return ob_get_clean();
}
