function frontend_edit_page_elementor_shortcode() {
    if (!is_user_logged_in() || !current_user_can('edit_pages')) {
        return '<p>Akses ditolak.</p>';
    }

    if (!did_action('elementor/loaded')) {
        return '<p>Elementor tidak aktif.</p>';
    }

    $page_id = isset($_GET['page_id_edit']) ? intval($_GET['page_id_edit']) : 0;
    $page    = get_post($page_id);

