function restrict_elementor_access_for_customers() {
    if ( isset($_GET['action']) && $_GET['action'] === 'elementor' && isset($_GET['post']) ) {
        $post_id = intval($_GET['post']);
        $post_author = get_post_field('post_author', $post_id);
        $current_user = get_current_user_id();

        // Cek jika role user adalah customer
        if (current_user_can('customer')) {
            if ($post_author != $current_user) {
                wp_die('Anda tidak memiliki izin untuk mengedit halaman ini.');
            }
        }
    }
}
add_action('admin_init', 'restrict_elementor_access_for_customers');

