    if (isset($_GET['page_id_edit']) && is_page('edit-page-elementor')) {
        $post_id = intval($_GET['page_id_edit']);
        $edit_link = admin_url('post.php?post=' . $post_id . '&action=elementor');
        wp_safe_redirect($edit_link);
        exit;
    }
}
add_action('template_redirect', 'redirect_to_elementor_editor');

function limit_admin_menu_for_customers() {
    if (current_user_can('affiliator_user')) {
        global $menu, $submenu;

        // Hapus semua menu utama selain Pages
        foreach ($menu as $key => $item) {
            if ($item[2] !== 'edit.php?post_type=page') {
                unset($menu[$key]);
            }
        }

        // Hapus submenu yang tidak perlu (opsional)
        unset($submenu['edit.php?post_type=page'][10]); // hapus "Add New" jika ingin
    }
}
add_action('admin_menu', 'limit_admin_menu_for_customers', 999);

