add_action('admin_init', function () {
    $user = wp_get_current_user();
    if (in_array('affiliator_user', (array) $user->roles)) {
        global $pagenow;

        // Izinkan hanya post.php dengan action elementor
        if ($pagenow === 'post.php' && isset($_GET['action']) && $_GET['action'] === 'elementor') {
            return; // OK
        }

        // Redirect ke home jika bukan halaman Elementor
        if ($pagenow !== 'admin-ajax.php') {
            wp_redirect(home_url());
            exit;
        }
    }
});

