// Fungsi untuk render halaman
function render_affiliator_update_page() {
    global $wpdb;

    echo '<div class="wrap">';
    echo '<h1>Update Role ke <code>affiliator_user</code></h1>';

    // Ambil semua user_id yang membership = 2
    $user_ids = $wpdb->get_col("SELECT idwp FROM {$wpdb->prefix}member WHERE membership = 2");

    if (empty($user_ids)) {
        echo '<p><strong>Tidak ada user dengan membership = 2.</strong></p>';
        echo '</div>';
        return;
    }

    // Ambil data user untuk preview
    $placeholders = implode(',', array_fill(0, count($user_ids), '%d'));
    $query = "
        SELECT u.ID, u.user_login, u.user_email, um.meta_value AS current_role
        FROM {$wpdb->users} u
        LEFT JOIN {$wpdb->usermeta} um
            ON u.ID = um.user_id
            AND um.meta_key = '{$wpdb->prefix}capabilities'
        WHERE u.ID IN ($placeholders)
    ";
    $prepared = $wpdb->prepare($query, $user_ids);
    $users = $wpdb->get_results($prepared);

    echo '<h2>Preview User</h2>';
    echo '<form method="post">';
    wp_nonce_field('update_affiliator_role_action', 'update_affiliator_role_nonce');

    echo '<table class="widefat fixed striped">';
    echo '<thead>
            <tr>
                <th>User ID</th>
                <th>Username</th>
                <th>Email</th>
                <th>Role Saat Ini</th>
                <th>Role Baru</th>
            </tr>
          </thead><tbody>';
    foreach ($users as $user) {
        $current_role = maybe_unserialize($user->current_role);
        $current_role_text = is_array($current_role)
            ? implode(', ', array_keys($current_role))
            : '(belum ada role)';

        echo '<tr>';
        echo '<td>' . esc_html($user->ID) . '</td>';
        echo '<td>' . esc_html($user->user_login) . '</td>';
        echo '<td>' . esc_html($user->user_email) . '</td>';
        echo '<td>' . esc_html($current_role_text) . '</td>';
        echo '<td><strong>affiliator_user</strong></td>';
        echo '</tr>';
    }
    echo '</tbody></table>';

    echo '<p><button type="submit" name="update_affiliator_roles" class="button button-primary">Update Semua</button></p>';
    echo '</form>';
    echo '</div>';

    // Proses update jika tombol diklik
    if (isset($_POST['update_affiliator_roles'])) {
        if (!isset($_POST['update_affiliator_role_nonce']) || !wp_verify_nonce($_POST['update_affiliator_role_nonce'], 'update_affiliator_role_action')) {
            wp_die('Keamanan gagal, coba lagi.');
        }

        // Serialize role baru
        $role_value = serialize(array('affiliator_user' => true));
        $user_ids_list = implode(',', array_map('intval', $user_ids));

        $wpdb->query(
            $wpdb->prepare(
                "UPDATE {$wpdb->prefix}usermeta 
                 SET meta_value = %s 
                 WHERE meta_key = '{$wpdb->prefix}capabilities' 
                 AND user_id IN ($user_ids_list)",
                $role_value
            )
        );

        echo '<div class="updated"><p><strong>Role berhasil diperbarui untuk ' . count($user_ids) . ' user.</strong></p></div>';
    }
}

