        // pastikan frontend.js tetap dimuat
        wp_enqueue_script(
            'yith-ywpar-frontend',
            plugins_url( 'yith-woocommerce-points-and-rewards-premium/assets/js/frontend.js' ),
            array( 'jquery', 'wc-cart' ),
            '1.0',
            true
        );

        // paksa definisikan variabel JS yang hilang
        wp_localize_script( 'yith-ywpar-frontend', 'yith_ywpar_general', array(
            'wc_ajax_url'       => WC_AJAX::get_endpoint( "%%endpoint%%" ),
            'cart_or_checkout'  => is_checkout() ? 'checkout' : 'cart',
            'redeem_uses_ajax'  => 'yes',
            'discount_value_nonce' => wp_create_nonce( 'ywpar-discount-value' ),
            'birthday_date_format' => 'yy-mm-dd',
            'datepicker'        => array(),
        ));
    }
}, 20 );


